WITH with_windows AS (SELECT id, supplier_name, city, AVG(rating) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS rating_avg_6_prior, AVG(rating) OVER (ORDER BY rating, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS rating_avg_2_prior, AVG(rating) OVER (ORDER BY rating, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS rating_avg_2_prior_2, NTILE(10) OVER (PARTITION BY country ORDER BY rating DESC, id) AS rating_bucket FROM suppliers WHERE country IN ('US', 'UK')) SELECT id, supplier_name, city, rating_avg_6_prior, rating_avg_2_prior_2, CASE WHEN city RLIKE '^(Berlin|Tokyo)$' THEN 'GROUP_A' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS city_zone FROM with_windows ORDER BY id NULLS FIRST;
